// csh / tcsh: backend + emitter. Single quotes stop everything except history '!' (escaped) and newlines
// (backslash-continued). csh has no functions (only `int main()` is inlined) and its command
// substitution drops newlines, so fs.read and forge::sh/shell results are emit errors here.
#include "shell.hpp"
#include "emit_dialect.hpp"
namespace {
using namespace forge::script;
std::string cq(const std::string& s) { std::string o = "'"; for (char c : s) { if (c == '\'') o += "'\\''"; else if (c == '!') o += "\\!"; else if (c == '\n') o += "\\\n"; else o += c; } return o + "'"; }
struct csh_dialect : block_dialect {
    csh_dialect() { has_functions = false; }
    std::string header() override { return "#!/bin/tcsh -f\n# generated by `forge script --emit " + cx->target + "`; runs without FORGE\n"; }
    static bool simple(const std::string& f) { return (!f.empty() && f[0] == '$') || (f.size() >= 2 && f.front() == '\'' && f.back() == '\'' && f.find('\'', 1) == f.size() - 1); }
    std::string tmp_str(const std::string& v) { auto t = cx->tmp(); L("set " + t + " = " + v); return "$" + t + ":q"; }
    std::string tmp_int(const std::string& expr) { auto t = cx->tmp(); L("@ " + t + " = ( " + expr + " )"); return "$" + t; }
    std::string s_lit(const std::string& s) override { return cq(s); }
    std::string ref(const std::string& n, ety t, bool) override { return t == ety::Int ? "$" + n : "$" + n + ":q"; }
    std::string arith(char op, const std::string& a, const std::string& b) override { return tmp_int(a + " " + op + " " + b); }
    std::string neg(const std::string& a) override { return tmp_int("0 - " + a); }
    std::string concat(const std::vector<std::string>& p) override { std::string o; for (auto& x : p) o += x; return o; }
    std::string i2s(const std::string& i) override { return i; }
    std::string s2i(const std::string& s) override { auto t = tmp_str(s); return tmp_int(t.substr(0, t.size() - 2)); }
    std::string slen(const std::string& s) override { auto t = tmp_str(s); auto n = t.substr(1, t.size() - 3); auto r = cx->tmp(); L("@ " + r + " = $%" + n); return "$" + r; }
    std::string operand(const std::string& f) { auto v = simple(f) ? f : tmp_str(f); if (v[0] == '$') return "\"" + v.substr(0, v.size() - 2) + "\""; return v; }
    std::string cmp(const std::string& op, const std::string& a, const std::string& b, bool ints) override {
        if (ints) return "( " + a + " " + op + " " + b + " )";
        if (op != "==" && op != "!=") no("string ordering with " + op);
        return "( " + operand(a) + " " + op + " " + operand(b) + " )";
    }
    std::string c_and(const std::string& a, const std::string& b) override { return "( " + a + " && " + b + " )"; }
    std::string c_or(const std::string& a, const std::string& b) override { return "( " + a + " || " + b + " )"; }
    std::string c_not(const std::string& a) override { return "! " + a; }
    std::string c_bool(bool v) override { return v ? "( 1 )" : "( 0 )"; }
    void let(const std::string& n, const std::string& v, ety t, bool, bool) override { L(t == ety::Int ? "@ " + n + " = ( " + v + " )" : "set " + n + " = " + v); }
    void print(const std::string& v, bool nl, bool err) override { L(err ? std::string("( printf '%s") + (nl ? "\\n" : "") + "' " + v + " > /dev/tty )" : std::string("printf '%s") + (nl ? "\\n" : "") + "' " + v); }
    void if_(const std::string& c) override { open("if " + c + " then"); }
    void else_() override { mid("else"); }
    void end_if() override { close("endif"); }
    void while_(const std::string& c) override { open("while " + c); }
    void end_while() override { close("end"); }
    void for_(const std::string& v, const std::vector<std::string>& items) override { std::string s; for (auto& i : items) s += " " + i; open("foreach " + v + " (" + s + " )"); }
    void end_for() override { close("end"); }
    void brk() override { L("break"); }
    void cont() override { L("continue"); }
    void fn_(const std::string&, const std::vector<std::string>&) override { no("functions"); }
    void end_fn() override {}
    void ret(const std::string&) override { no("return"); }
    std::string call(const std::string& name, const std::vector<std::string>&, bool, ety) override { no("calling " + name + " (csh has no functions)"); }
    void exit_(const std::string& c) override { L("exit " + c); }
    std::string env(const std::string& n, const std::string& d) override {
        std::string name; if (!lit_name(n, '\'', name)) no("a dynamic environment variable name");
        auto t = cx->tmp(); L("set " + t + " = " + d);
        if_("( $?" + name + " )"); L("set " + t + " = $" + name + ":q"); end_if();
        return "$" + t + ":q";
    }
    void setenv(const std::string& n, const std::string& v) override { std::string name; if (!lit_name(n, '\'', name)) no("a dynamic environment variable name"); L("setenv " + name + " " + v); }
    std::string test_path(const std::string& p, char k) override { return std::string("( -") + k + " " + operand(p) + " )"; }
    void mkdir(const std::string& p) override { L("mkdir -p -- " + p); }
    void remove(const std::string& p) override { L("rm -rf -- " + p); }
    void write(const std::string& p, const std::string& s, bool app) override { L("printf '%s' " + s + (app ? " >> " : " >! ") + p); }
    std::string read(const std::string&) override { no("fs.read (csh command substitution drops newlines)"); }
    std::string cwd() override { auto t = cx->tmp(); L("set " + t + " = \"`pwd -P`\""); return "$" + t + ":q"; }
    std::string platform() override {
        auto t = cx->tmp(); L("set " + t + " = `uname -s`");
        L("switch ( $" + t + " )"); in();
        for (auto [k, v] : {std::pair{"Linux", "linux"}, std::pair{"Darwin", "macos"}, std::pair{"FreeBSD", "freebsd"}, std::pair{"MINGW*", "windows"}, std::pair{"MSYS*", "windows"}, std::pair{"CYGWIN*", "windows"}, std::pair{"Windows_NT", "windows"}}) { L(std::string("case ") + k + ":"); L(std::string("    set ") + t + " = " + v); L("    breaksw"); }
        L("default:"); L("    set " + t + " = other"); out(); L("endsw");
        if_("( $" + t + " == linux && $?ANDROID_ROOT )"); L("set " + t + " = android"); end_if();
        return "$" + t + ":q";
    }
    void run(const std::string&, const std::string&, const std::string&, bool) override { no("forge::sh / forge::shell results (csh command substitution drops newlines)"); }
    std::string sh_quote(const std::string&) override { no("forge::sh"); }
};
} // namespace
void forge_shell_register_csh(forge::script::shell_registry& r) {
    for (auto [n, e, t] : {std::tuple{"tcsh", "tcsh", true}, std::tuple{"csh", "csh", false}}) {
        forge::script::shell_backend b; b.name = n; b.exes = {e}; if (std::string(n) == "csh") b.exes.push_back("tcsh");
        b.family = "csh"; b.golden_tested = t; b.quote = cq; b.notes = std::string(n) == "csh" ? "falls back to tcsh" : "";
        b.argv = [](const std::string& exe, const std::string& sc) -> std::vector<std::string> { return {exe, "-f", "-c", sc}; };
        b.emitter = [] { return std::make_unique<csh_dialect>(); }; b.emit_ext = ".csh"; b.emit_tested = t;
        r.add(std::move(b));
    }
}
